const D = { energy:.6, density:.5, scale:1, speed:1, hue:104, moisture:.6, x:.5, y:.5, style:'microscopy', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7) * 43758.5453; return s - Math.floor(s); };
const sty = P.style;
const EN = cl(P.energy,0,1), DN = cl(P.density,0,1), SC = cl(P.scale,.35,2.4);
const AL = cl(P.alpha,0,100)/100;

if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dt = K.t - S.lastT; S.lastT = K.t;
if (!(dt >= 0) || dt > .25) dt = 1/60;
const SP = cl(P.speed,.05,4);
S.tt = (S.tt || 0) + dt*SP;
const T = S.tt;
const gust = .9*Math.sin(T*.61) + .5*Math.sin(T*1.43+1.7) + .32*Math.sin(T*2.29);
const breeze = (.3 + .9*EN)*gust + A.lowmid*.8 + K.pulse*.24*K.intensity;
// wet/dry breathing — a whole-frame colour+swell cycle on incommensurate rates
const wet = cl(cl(P.moisture,0,1)*.62 + .38*(.5 + .5*Math.sin(T*.047) + .18*Math.sin(T*.113+2.1)), 0, 1);

// ---- field ---------------------------------------------------------------
const GW = Math.round(cl(128/SC, 40, 190));
const GH = Math.max(8, Math.round(GW*height/Math.max(1,width)));
const N = GW*GH;
const fKey = [GW,GH,sd].join('|');
if (!S.sp || S.fKey !== fKey) {
  S.fKey = fKey;
  S.sp = new Uint8Array(N);      // 0 rock · 1 moss cushion · 2 liverwort thallus · 3 necrotic
  S.bio = new Float32Array(N);
  S.ag = new Float32Array(N);
  S.ax = new Uint8Array(N);      // liverwort growth axis (dichotomous forking)
  S.mot = new Float32Array(N);   // per-cell granite/tuft mottle
  for (let i=0;i<N;i++) S.mot[i] = fr(i*1.7)*.55 + fr(i*4.3)*.45;
  S.rng = (sd*2654435761 + 12345) >>> 0;
  S.cur = 0;
  if (S.fb && S.fb.remove) S.fb.remove();
  S.fb = createGraphics(GW, GH); S.fb.pixelDensity(1);
  for (let k=0;k<26;k++){                                   // inoculate around the P.x/P.y focus
    const i = Math.floor(cl(P.x + (fr(k*3.7)-.5)*.7, .02, .98)*GW)
            + Math.floor(cl(P.y + (fr(k*5.1)-.5)*.7, .02, .98)*GH)*GW;
    S.sp[i] = fr(k*2.3) < .55 ? 1 : 2; S.bio[i] = .3; S.ag[i] = 0; S.ax[i] = (fr(k*7.9)*4)|0;
  }
  S.warm = 0;
}
const rnd = () => { S.rng = (Math.imul(S.rng, 1664525) + 1013904223) >>> 0; return S.rng / 4294967296; };

const MOSS_MAT = 16, LIV_MAT = 13, MOSS_OLD = 30, LIV_OLD = 26;
const sp = S.sp, bio = S.bio, ag = S.ag, ax = S.ax;
const step = (i, dtc) => {
  const s0 = sp[i];
  if (s0 === 0) {                                          // bare rock — contact-inhibited colonisation
    const x = i % GW, y = (i/GW)|0;
    let best = 0, bb = 0, bax = 0;
    for (let d=0; d<4; d++) {
      const nx = x + (d===0?1:(d===1?-1:0)), ny = y + (d===2?1:(d===3?-1:0));
      if (nx < 0 || nx >= GW || ny < 0 || ny >= GH) continue;
      const j = nx + ny*GW; const sj = sp[j];
      if (sj !== 1 && sj !== 2) continue;
      let w = bio[j];
      if (sj === 2) w *= (ax[j] === (d^1)) ? 2.6 : .16;     // liverwort spreads along its own axis
      if (w > bb) { bb = w; best = sj; bax = (d^1); }
    }
    if (bb > .28 && rnd() < bb*dtc*(.5 + 1.5*wet)*(.6 + .8*EN)*.9) {
      sp[i] = best; bio[i] = .05; ag[i] = 0;
      // dichotomous fork: turn perpendicular (0/1 are horizontal, 2/3 vertical)
      ax[i] = (best === 2 && rnd() < .09) ? (bax < 2 ? (rnd()<.5?2:3) : (rnd()<.5?0:1)) : bax;
    }
    return;
  }
  if (s0 === 3) { bio[i] -= dtc*.13; if (bio[i] <= 0) { sp[i] = 0; bio[i] = 0; ag[i] = 0; } return; }
  ag[i] += dtc;
  const oldA = s0 === 1 ? MOSS_OLD : LIV_OLD;
  bio[i] += dtc*(.10 + .16*wet)*(1 - bio[i]);
  if (bio[i] > 1) bio[i] = 1;
  if (ag[i] > oldA*(.7 + S.mot[i]*.7)) { sp[i] = 3; }       // necrotic centre — the turnover
};
const sweep = d => {
  const chunk = Math.ceil(N/5);
  const dtc = d*5;
  for (let q=0;q<chunk;q++){ const i = S.cur; S.cur = (S.cur + 1) % N; step(i, dtc); }
  if (rnd() < d*(2.5 + DN*7)) {                            // spore rain reseeds bare rock
    const i = (rnd()*N)|0;
    if (sp[i] === 0) { sp[i] = rnd() < .6 ? 1 : 2; bio[i] = .05; ag[i] = 0; ax[i] = (rnd()*4)|0; }
  }
};
if (!S.warm) { S.warm = 1; for (let q=0;q<300;q++) sweep(1/12); }   // mat already established
sweep(dt*SP);

// ---- colour LUTs (rebuilt each frame — 4 species x 40 tones, ~160 conversions)
if (!S.lut) S.lut = new Uint8Array(4*40*3);
const lut = S.lut;
const putHSB = (o, h, s, b) => {
  h = ((h % 360) + 360) % 360; s = cl(s,0,1); b = cl(b,0,1);
  const c = b*s, x = c*(1 - Math.abs(((h/60) % 2) - 1)), m = b - c;
  let r, g2, bl;
  if (h < 60) { r=c; g2=x; bl=0; } else if (h < 120) { r=x; g2=c; bl=0; }
  else if (h < 180) { r=0; g2=c; bl=x; } else if (h < 240) { r=0; g2=x; bl=c; }
  else if (h < 300) { r=x; g2=0; bl=c; } else { r=c; g2=0; bl=x; }
  lut[o] = (r+m)*255; lut[o+1] = (g2+m)*255; lut[o+2] = (bl+m)*255;
};
const HU = P.hue;
for (let t2=0;t2<40;t2++) {
  const v = t2/39;
  if (sty === 'cyanotype') {
    putHSB(0*120 + t2*3, 214, .84 - v*.1, .17 + v*.14);                        // rock
    putHSB(1*120 + t2*3, 214, .5 - v*.44, .3 + v*.68);                         // moss -> white photogram
    putHSB(2*120 + t2*3, 208, .62 - v*.4, .24 + v*.5);                         // liverwort
    putHSB(3*120 + t2*3, 218, .7 - v*.2, .2 + v*.2);                           // necrotic
  } else if (sty === 'ink_wash') {
    putHSB(0*120 + t2*3, 36, .07, .74 - v*.12);
    putHSB(1*120 + t2*3, 32, .1 + v*.06, .66 - v*.5);
    putHSB(2*120 + t2*3, 30, .06, .58 - v*.3);
    putHSB(3*120 + t2*3, 30, .1, .6 - v*.18);
  } else if (sty === 'false_color') {
    putHSB(0*120 + t2*3, 250, .5, .1 + v*.06);
    putHSB(1*120 + t2*3, 300 - v*300, .85, .28 + v*.68);                       // ironbow on biomass
    putHSB(2*120 + t2*3, 190 - v*80, .8, .24 + v*.6);
    putHSB(3*120 + t2*3, 262, .55, .16 + v*.14);
  } else {
    putHSB(0*120 + t2*3, 34 - v*8, .1 + v*.06 + wet*.05, .5 - v*.2 - wet*.05); // damp granite
    putHSB(1*120 + t2*3, HU + 8 - v*14, .3 + v*.42*(.55 + .55*wet), .17 + v*.42*(.8 + .3*wet));
    putHSB(2*120 + t2*3, HU + 52 - v*10, .26 + v*.3*(.5 + .6*wet), .15 + v*.3*(.85 + .25*wet));
    putHSB(3*120 + t2*3, 30 - v*6, .3 + v*.24, .22 + v*.2);
  }
}

// ---- rasterise the field ------------------------------------------------
const fb = S.fb;
fb.loadPixels();
const px = fb.pixels;
for (let i=0;i<N;i++) {
  const s0 = sp[i];
  let v;
  if (s0 === 0) v = S.mot[i];
  else if (s0 === 3) v = bio[i]*.8 + S.mot[i]*.2;
  else v = cl(bio[i]*(.7 + .3*wet) + (S.mot[i]-.5)*.24 + (ag[i] > (s0===1?MOSS_MAT:LIV_MAT) ? .08 : 0), 0, 1);
  let t2 = (v*39)|0; if (t2 < 0) t2 = 0; else if (t2 > 39) t2 = 39;
  const o = s0*120 + t2*3, p4 = i*4;
  px[p4] = lut[o]; px[p4+1] = lut[o+1]; px[p4+2] = lut[o+2]; px[p4+3] = 255;
}
fb.updatePixels();
image(fb, 0, 0, width, height);

// ---- grain overlay: breaks the upscale's flatness back into rock tooth ---
const oKey = [width,height,sd,sty].join('|');
if (!S.ov || S.oKey !== oKey) {
  S.oKey = oKey;
  const ow = Math.min(560, Math.max(200, width|0)), oh = Math.max(1, Math.round(ow*height/Math.max(1,width)));
  const g = (S.ov && S.ov.width === ow && S.ov.height === oh) ? S.ov : createGraphics(ow, oh);
  S.ov = g; g.colorMode(HSB, 360, 100, 100, 100);
  g.push(); g.clear(); g.noStroke();
  for (let i=0;i<9000;i++){ g.fill(0, 0, fr(i*2.9)*100, 15 + fr(i*5.3)*22);
    g.rect(fr(i*3.1)*ow, fr(i*7.3+4)*oh, 1.3, 1.3); }
  g.pop();
}
blendMode(MULTIPLY); tint(0, 0, 100, 34); image(S.ov, 0, 0, width, height);
noTint(); blendMode(BLEND);

// ---- live vectors: moss tufts + sporophyte setae (the motion floor) ------
const cw = width/GW, chh = height/GH;
const idx = (gx, gy) => (gx|0) + ((gy|0))*GW;
const nTuft = Math.round(30 + DN*170);
const tuftL = u*.016*SC*(.7 + .5*wet);
strokeCap(ROUND); noFill();
for (let k=0;k<nTuft;k++) {
  const gx = fr(k*1.9)*GW, gy = fr(k*3.7+1)*GH;
  const i = idx(gx, gy); const s0 = sp[i];
  if (s0 !== 1 && s0 !== 2) continue;
  const bx = gx*cw, by = gy*chh;
  const vit = bio[i];
  const sw2 = breeze*u*.004*vit*(.5 + .8*Math.sin(T*2.7 + k*1.31));
  const L = tuftL*(.4 + .8*vit)*(s0 === 2 ? .55 : 1);
  if (sty === 'cyanotype') stroke(214, 14, 92, 40*AL*vit);
  else if (sty === 'ink_wash') stroke(30, 14, 26, 34*AL*vit);
  else if (sty === 'false_color') stroke(300 - vit*300, 85, 96, 34*AL*vit);
  else stroke(P.hue + (s0===2?52:6), 40 + 26*wet, 22 + 44*vit, 40*AL*vit);
  strokeWeight(Math.max(.55, u*.0016*SC));
  const nStrk = nTuft > 120 ? (s0===1?2:1) : (s0===1?3:2);   // budget: shoots per tuft
  for (let q=0;q<nStrk;q++){
    const aa = -Math.PI*.5 + (q-1)*.62 + fr(k*9.1+q)*.4 - .2;
    beginShape(); vertex(bx, by);
    vertex(bx + Math.cos(aa)*L*.5 + sw2*.4, by + Math.sin(aa)*L*.5);
    vertex(bx + Math.cos(aa)*L + sw2, by + Math.sin(aa)*L);
    endShape();
  }
}
const nSeta = Math.round(16 + DN*100);
for (let k=0;k<nSeta;k++) {
  const gx = fr(k*5.3+7)*GW, gy = fr(k*2.1+3)*GH;
  const i = idx(gx, gy);
  if (sp[i] !== 1 || ag[i] < MOSS_MAT) continue;
  const rip = cl((ag[i] - MOSS_MAT)/12, 0, 1);              // ripeness drives height + nod
  const bx = gx*cw, by = gy*chh;
  const hgt = u*.055*SC*rip*(.6 + .55*wet)*(.7 + .5*bio[i]);
  const ph = fr(k*11.3)*6.28;
  const nod = (.35 + .5*rip)*(.5 + .6*Math.sin(T*1.7 + ph));
  const sw2 = breeze*u*.014*(.5 + .9*Math.sin(T*1.19 + ph*1.4)) + Math.sin(T*3.1 + ph)*u*.002*EN;
  const tx = bx + sw2 + Math.cos(-Math.PI*.5 + nod*.9)*hgt*.12, ty = by - hgt;
  if (sty === 'cyanotype') stroke(214, 8, 96, 78*AL);
  else if (sty === 'ink_wash') stroke(28, 20, 18, 66*AL);
  else if (sty === 'false_color') stroke(58, 90, 98, 70*AL);
  else stroke(28 + rip*8, 44 + rip*26, 46 + rip*26, 76*AL);
  strokeWeight(Math.max(.7, u*.0016*SC)); noFill();
  beginShape();
  for (let q=0;q<=4;q++){ const v = q/4;
    vertex(bx + sw2*v*v*1.2 + nod*hgt*.2*v*v, by - hgt*v); }
  endShape();
  const cr = u*.011*SC*rip*(.7 + .3*bio[i]);                // the capsule, nodding
  noStroke();
  if (sty === 'cyanotype') fill(214, 4, 99, 88*AL);
  else if (sty === 'ink_wash') fill(28, 22, 22, 78*AL);
  else if (sty === 'false_color') fill(48, 95, 100, 82*AL);
  else fill(26 + rip*10, 52 + rip*22, 40 + rip*34, 88*AL);
  push(); translate(tx, ty); rotate(nod*.8 + Math.PI*.06);
  ellipse(0, 0, cr*.72, cr*1.5); pop();
  if (rip > .85 && nSeta <= 70) {                            // dehiscence — spores away
    for (let q=0;q<3;q++){
      const dph = (T*.31 + fr(k*13.7+q)*7) % 1;
      noStroke();
      if (sty === 'cyanotype') fill(214, 2, 100, 52*AL*(1-dph));
      else if (sty === 'ink_wash') fill(28, 12, 34, 40*AL*(1-dph));
      else fill(46, 34, 88, 46*AL*(1-dph));
      ellipse(tx + Math.sin(T*.9 + q*2.1 + k)*u*.05*dph + breeze*u*.06*dph,
              ty - dph*u*.09, u*.0035*SC, u*.0035*SC);
    }
  }
}
